const j=$input.first().json;
for(const k of ['learning_objective','age_band','reference_image']) if(!j[k]) throw new Error(k+' required');
if(!Array.isArray(j.fact_sources)||!j.fact_sources.length) throw new Error('fact_sources must contain dated/authoritative references');
if(j.age_band==='under_5'&&!j.adult_review_required) throw new Error('adult review required for child-directed material');
return [{json:{brief_id:String(j.brief_id||'kids-'+Date.now()),learning_objective:j.learning_objective,age_band:j.age_band,reference_image:j.reference_image,fact_sources:j.fact_sources,storyboard_status:'prepared_for_human_review',render_adapter:'PENDING: configured Higgsfield or supplied local graph/worker',generation_status:'not_generated',qa:['age_appropriate_language','factual_review','original_art','audio_caption_check'],publish_status:'disabled'}}];
